const float4 samples[5] = {
    0.0,    0.0,    0,    11.0/3.0,
    0.0,    1.0,    0,    -2.0/3.0,
    0.0,    -1.0,   0,    -2.0/3.0,
    -1.0,    0.0,   0,    -2.0/3.0,
    1.0,    0.0,   0,    -2.0/3.0
};

sampler sampler_smalltiled_ensign_meat;

shader_body
{
    float2 d = texsize.zw*8;
    float1 dx = ( GetBlur1(uv.yx+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) ).y;
    float1 dy = ( GetBlur1(uv.yx+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) ).y;
    float2 uv_y = uv+float2(dy,dx)*0.55;  
    float2 uv_y2 = (uv_y*1.25)-.125;  


    ret = lerp(ret,1-ret,.7*GetBlur1(uv_y)+.2*GetPixel(uv.yx));
    ret = lerp(ret,ret-.1*GetBlur3(uv_y)+.1*GetBlur1(uv_y2)+.42*GetPixel(uv_y),.25);
    //ret *= .75;
    ret *= saturate(length(ret-0.5)*5);
    //ret = ret.xy;
    ret = lum(ret);
    ret += 1.25;
    ret *= ret*.45;
    float3 mask = GetBlur3(uv)-GetBlur1(uv)-.25*GetBlur2(uv_y);
    ret *= lerp(ret,1.3*ret*mask,pow(hue_shader.zxy,ret));
    ret *=1;


    float3 a_varaible = 0; 
    for(int i=0;i<5;i++)
      a_varaible += samples[i].w*tex2D(sampler_smalltiled_ensign_meat,ret*0.1+
       float2(samples[i].x*(1/texsize.x),
              samples[i].y*(1/texsize.y)))*0.2;

    ret = (a_varaible);
    ret = 1 - (ret   + GetBlur3(ret)*1);
ret=.4-ret;
}

