{
    // use 3D noise 
    float3 uvw = float3(uv*3.3, 0.3);
    //uvw = mul(uvw, rot_s2);
    uvw.z += time*0.3;

    // sample a high-quality 3D noise volume!
    float4 N = tex3D(sampler_noisevol_hq, uvw);

    float2 uv2 = uv;
    uv2 += (N.xy*2-1)*texsize.zw*15*sin(0.5*time);

