                      ((uv.xyy
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*0.4 
                     );
if(ret.x+ret.y+ret.z>.5)ret += (noise2)*.5; 

