Bdrv Aderrasi - Contortion Sphere bdrv e.comp:
sampler sampler_fc_sunrise;
float2 factorA, factorB, product;
float2 numerator, denominator, fraction;
shader_body
{
float2 uvo = uv;
uv = (uv-0.5);
factorA = uv+ float2(q1,q2);
factorB = float2(8,0);
product = float2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
float2 uv1 = product;
factorA = uv+ float2(q3,q4);
factorB = float2(8,0);
product = float2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
float2 uv2 = product;
factorA = uv+ float2(q5,q6);
factorB = float2(8,0);
product = float2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
float2 uv3 = product;
factorA = uv+ float2(q7,q8);
factorB = float2(8,0);
product = float2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
float2 uv4 = product;
factorA = uv1;
factorB = uv2;
product = float2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
float2 uv12 = product;
factorA = uv3;
factorB = uv4;
product = float2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
float2 uv34 = product;
factorA = uv12;
factorB = uv34;
product = float2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
numerator = float2(1,0);
denominator = product;
fraction = float2( numerator.x*denominator.x + numerator.y*denominator.y,   // the fractions real part
                   numerator.y*denominator.x - numerator.x*denominator.y)/  // the fractions imaginary part
                   (denominator.x*denominator.x + denominator.y*denominator.y);
uv = fraction*16;
uv = lerp(0.5 + (uvo-0.5)*2,uv+0.5,0.5);
uv = 0.5 + (1.0 - abs( frac( uv * 0.5 ) * 2 - 1.0 )-0.5); // Eo.S. mirror code with cutted borders

ret = tex2D( sampler_fc_main, uv );

}

